const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Kornwerderzand: ~53.075°N, 5.335°E (eastern end of Afsluitdijk)
  // Afsluitdijk comparison point: ~53.05°N, 5.15°E (middle of causeway)
  const kornwerderzand = ee.Geometry.Point([5.335, 53.075]);
  const afsluitdijk = ee.Geometry.Point([5.15, 53.05]);

  const startDate = '2023-07-08';
  const endDate = '2023-07-09';

  // 2. Data Acquisition
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(kornwerderzand)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size = await collection.size().getInfo();
  console.log(`Images found: ${size}`);

  if (size === 0) {
    // Try wider date range
    collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate('2023-07-07', '2023-07-10')
      .filterBounds(kornwerderzand)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

    const size2 = await collection.size().getInfo();
    console.log(`Images with wider range: ${size2}`);

    if (size2 === 0) {
      console.log("No images available for the date.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Get best image and mask clouds
  const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  const cloudMask = image.select('QA60').bitwiseAnd(1024).eq(0)
    .and(image.select('QA60').bitwiseAnd(2048).eq(0));

  const maskedImage = image.updateMask(cloudMask);

  // Calculate greenness using Green/Red ratio
  const greenness = maskedImage.select('B3').divide(maskedImage.select('B4'));

  // 4. Extract values at both locations
  const params = {
    reducer: ee.Reducer.mean(),
    scale: 10,
    maxPixels: 1e9
  };

  const kornValue = await greenness.reduceRegion({
    ...params,
    geometry: kornwerderzand.buffer(50)
  }).get('B3').getInfo();

  const afsluitValue = await greenness.reduceRegion({
    ...params,
    geometry: afsluitdijk.buffer(50)
  }).get('B3').getInfo();

  // Check pixel counts
  const kornCount = await maskedImage.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: kornwerderzand.buffer(50),
    scale: 10,
    maxPixels: 1e9
  }).get('B3').getInfo();

  const afsluitCount = await maskedImage.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: afsluitdijk.buffer(50),
    scale: 10,
    maxPixels: 1e9
  }).get('B3').getInfo();

  console.log(`Kornwerderzand: Green/Red=${kornValue?.toFixed(3)}, Pixels=${kornCount}`);
  console.log(`Afsluitdijk: Green/Red=${afsluitValue?.toFixed(3)}, Pixels=${afsluitCount}`);

  // 5. Validation & Final Answer
  if (kornCount === 0 || afsluitCount === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (kornValue === null || afsluitValue === null || 
      isNaN(kornValue) || isNaN(afsluitValue)) {
    console.log("Calculation failed - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Higher Green/Red ratio = greener
  if (kornValue > afsluitValue) {
    console.log("Kornwerderzand was visibly greener.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Kornwerderzand was not greener than Afsluitdijk.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
